 * and clear the history of opened URLs.
 *
 * @param {string} url - The URL to check.
 * @returns {boolean}
 */
assertHasLoadedURL(url) {
  Assert.equal(
    this.urls.length,
    1,
    "should have attempted to open exactly 1 URL in a browser"
  );
  Assert.equal(
    this.urls[0],
    url,
    "should have attempted to open the right URL"
  );
  this.urls.length = 0;
},
